    if (this.settingsPanel) return;

    const W = 280, H = 140;
    const cx = 200, cy = 300;

    // 반투명 배경 (터치 차단)
    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.5)
      .setDepth(50).setInteractive();

