        const removeBg = this.add.rectangle(cx - 92, BTN_Y, BTN_W, BTN_H, 0x331111)
          .setStrokeStyle(2, 0x884444)
          .setInteractive({ useHandCursor: true });
        removeBg.on('pointerover', () => removeBg.setFillStyle(0x442222));
