    closeBtnBg.on('pointerout',  () => closeBtnBg.setFillStyle(0x1a1a1a));
    closeBtnBg.on('pointerup',   () => this.hideCharacterDetail());
    panel.add(closeBtnBg);
    panel.add(this.add.text(cx + 92, BTN_Y, '닫기', {
